def compute(vars):
    old_rate = vars["v1"]
    new_rate = vars["v2"]

    if old_rate == 0:
        return None

    decrease = old_rate - new_rate
    change_ratio = decrease / old_rate
    value = change_ratio * 100

    return {
        "value": value,
        "trace": {
            "old_rate": old_rate,
            "new_rate": new_rate,
            "decrease": decrease,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
